  // to distinguish between "(0, eval)()" and "eval()".
  if (first != null && first.isName() &&
      "eval".equals(first.getString())) {
    first.putBooleanProp(Node.DIRECT_EVAL, true);
  }
}

public static boolean isJSIdentifier(String s) {
  int length = s.length();

  if (length == 0 ||
      !Character.isLetter(s.charAt(0)) && s.charAt(0) != '$' && s.charAt(0) != '_') {
    return false;
  }

  for (int i = 1; i < length; i++) {
    char c = s.charAt(i);
    if (!Character.isLetterOrDigit(c) && c != '$' && c != '_') {
      return false;
    }
  }

  return true;
}

public void matchConstraint(JSType constraint) {
  // We only want to match constraints on anonymous types.
  if (hasReferenceName()) {
    return;
  }

  // Handle the case where the constraint object is a record type.
  //
  // param constraint {{prop: (number|undefined)}}
  // function f(constraint) {}
  // f({});
  //
  // We want to modify the object literal to match the constraint, by
  // taking each property on the record and trying to match
  // properties on this object.
  if (constraint.isRecordType()) {
    matchRecordTypeConstraint(constraint.toObjectType());
  } else if (constraint.isUnionType()) {
    // Handle the case where the constraint is a union type.
    // We need to ensure that the object matches at least one of the types in the union.
    for (JSType alternate : constraint.toMaybeUnionType().getAlternates()) {
      if (alternate.isRecordType()) {
        matchRecordTypeConstraint(alternate.toObjectType());
      }
    }
  }
  // Additional constraint handling can be added here if necessary.
}

@Override public void visit(NodeTraversal t, Node n, Node parent) {
  if (t.inGlobalScope()) {
    return;
  }

  if (n.isReturn() && n.getFirstChild() != null) {
    data.get(t.getScopeRoot()).recordNonEmptyReturn();
  }

  // The first-order function analyzer looks at two types of variables:
  //
  // 1) Local variables that are assigned in inner scopes ("escaped vars")
  //
  // 2) Local variables that are assigned more than once.
  //
  // We treat all global variables as escaped by default, so there's
  // no reason to do this extra computation for them.
  // Removed the condition that was prematurely returning, as it was preventing the analysis of deeper scopes.

  if (n.isName() && NodeUtil.isLValue(n) &&
      // Be careful of bleeding functions, which create variables
      // in the inner scope, not the scope where the name appears.
      !NodeUtil.isBleedingFunctionName(n)) {
    String name = n.getString();
    Scope scope = t.getScope();
    Var var = scope.getVar(name);
    if (var != null) {
      Scope ownerScope = var.getScope();
      if (ownerScope.isLocal()) {
        data.get(ownerScope.getRootNode()).recordAssignedName(name);
      }

      if (scope != ownerScope && ownerScope.isLocal()) {
        data.get(ownerScope.getRootNode()).recordEscapedVarName(name);
      }
    }
  } else if (n.isGetProp() && n.isUnscopedQualifiedName() &&
      NodeUtil.isLValue(n)) {
    String name = NodeUtil.getRootOfQualifiedName(n).getString();
    Scope scope = t.getScope();
    Var var = scope.getVar(name);
    if (var != null) {
      Scope ownerScope = var.getScope();
      if (scope != ownerScope && ownerScope.isLocal()) {
        data.get(ownerScope.getRootNode())
            .recordEscapedQualifiedName(n.getQualifiedName());
      }
    }
  }
}

protected void declareNameInScope(FlowScope scope, Node node, JSType type) {
  switch (node.getType()) {
    case Token.NAME:
      scope.inferSlotType(node.getString(), type);
      break;

    case Token.GETPROP:
      String qualifiedName = node.getQualifiedName();
      Preconditions.checkNotNull(qualifiedName);

      JSType origType = node.getJSType();
      origType = origType == null ? getNativeType(UNKNOWN_TYPE) : origType;
      scope.inferQualifiedSlot(node, qualifiedName, origType, type);
      break;

    case Token.THIS:
      // Assuming we want to handle 'this' in some way, for example, by declaring it as a specific type
      // or ignoring it. Here, we'll just ignore it as the comment suggests it's not modeled in the CFG.
      break;

    default:
      throw new IllegalArgumentException("Node cannot be refined. \n" +
          node.toStringTree());
  }
}

private void checkInterfaceConflictProperties(NodeTraversal t, Node n,
    String functionName, HashMap<String, ObjectType> properties,
    HashMap<String, ObjectType> currentProperties,
    ObjectType interfaceType) {
  ObjectType implicitProto = interfaceType.getImplicitPrototype();
  Set<String> currentPropertyNames;
  // This can be the case if interfaceType is proxy to a non-existent
  // object (which is a bad type annotation, but shouldn't crash).
  if (implicitProto != null) {
    currentPropertyNames = implicitProto.getOwnPropertyNames();
    for (String name : currentPropertyNames) {
      ObjectType oType = properties.get(name);
      if (oType != null) {
        if (!interfaceType.getPropertyType(name).isEquivalentTo(
            oType.getPropertyType(name))) {
          compiler.report(
              t.makeError(n, INCOMPATIBLE_EXTENDED_PROPERTY_TYPE,
                  functionName, name, oType.toString(),
                  interfaceType.toString()));
        }
      }
      currentProperties.put(name, interfaceType);
    }
  }
  for (ObjectType iType : interfaceType.getCtorExtendedInterfaces()) {
    checkInterfaceConflictProperties(t, n, functionName, properties,
        currentProperties, iType);
  }
}

void add(String newcode) {
  maybeEndStatement();

  if (newcode.length() == 0) {
    return;
  }

  char c = newcode.charAt(0);
  if ((isWordChar(c) || c == '\\') &&
      isWordChar(getLastChar())) {
    // need space to separate. This is not pretty printing.
    // For example: "return foo;"
    append(" ");
    // Do not allow a forward slash to appear after a DIV.
    // For example,
    // REGEXP DIV REGEXP
    // is valid and should print like
    // / // / /
  } else if (c == '/' && getLastChar() == '/') {
    // Ensure that we do not get // which is a comment start in JavaScript
    append(" ");
  }

  append(newcode);
}

public String getLine(int lineNumber) {
  String js = "";
  try {
    // NOTE(nicksantos): Right now, this is optimized for few warnings.
    // This is probably the right trade-off, but will be slow if there
    // are lots of warnings in one file.
    js = getCode();
  } catch (IOException e) {
    return null;
  }

  int pos = 0;
  int startLine = 1;

  // If we've saved a previous offset and it's for a line less than the
  // one we're searching for, then start at that point.
  if (lineNumber >= lastLine) {
    pos = lastOffset;
    startLine = lastLine;
  }

  for (int n = startLine; n < lineNumber; n++) {
    int nextpos = js.indexOf('\n', pos);
    if (nextpos == -1) {
      return null;
    }
    pos = nextpos + 1;
  }

  // Remember this offset for the next search we do.
  lastOffset = pos;
  lastLine = lineNumber;

  // Check if pos is already at the end of the string.
  if (pos >= js.length()) {
    return null;
  }

  int nextNewLine = js.indexOf('\n', pos);
  if (nextNewLine == -1) {
    // If next new line cannot be found, it means pos is at the last line of the file.
    return js.substring(pos);
  } else {
    return js.substring(pos, nextNewLine);
  }
}

private static String extractClassNameIfGoog(Node node, Node parent, String functionName) {
  String className = null;
  if (NodeUtil.isExprCall(parent)) {
    Node callNode = parent.getFirstChild();
    if (callNode != null && callNode.getType() == Token.CALL) {
      Node callee = callNode.getFirstChild();
      if (callee != null && callee.getType() == Token.GETPROP) {
        String qualifiedName = callee.getQualifiedName();
        if (functionName.equals(qualifiedName)) {
          Node target = callee.getNext();
          if (target != null && target.getType() == Token.STRING) {
            className = target.getString();
          }
        }
      }
    }
  }
  return className;
}

