public void visit(NodeTraversal t, Node n, Node parent) {
  JSType childType;
  JSType leftType, rightType;
  Node left, right;
  // To be explicitly set to false if the node is not typeable.
  boolean typeable = true;

  switch (n.getType()) {
    case Token.NAME:
      typeable = visitName(t, n, parent);
      break;

    case Token.LP:
      // If this is under a FUNCTION node, it is a parameter list and can be
      // ignored here.
      if (parent.getType() != Token.FUNCTION) {
        ensureTyped(t, n, getJSType(n.getFirstChild()));
      } else {
        typeable = false;
      }
      break;

    case Token.COMMA:
      ensureTyped(t, n, getJSType(n.getLastChild()));
      break;

    case Token.TRUE:
    case Token.FALSE:
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.THIS:
      ensureTyped(t, n, t.getScope().getTypeOfThis());
      break;

    case Token.REF_SPECIAL:
      ensureTyped(t, n);
      break;

    case Token.GET_REF:
      ensureTyped(t, n, getJSType(n.getFirstChild()));
      break;

    case Token.NULL:
      ensureTyped(t, n, NULL_TYPE);
      break;

    case Token.NUMBER:
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.STRING:
      // Object literal keys are handled with OBJECTLIT
      if (!NodeUtil.isObjectLitKey(n, n.getParent())) {
        ensureTyped(t, n, STRING_TYPE);
      } else {
        // Object literal keys are not typeable
        typeable = false;
      }
      break;

    case Token.GET:
    case Token.SET:
      // Object literal keys are handled with OBJECTLIT
      break;

    case Token.ARRAYLIT:
      ensureTyped(t, n, ARRAY_TYPE);
      break;

    case Token.REGEXP:
      ensureTyped(t, n, REGEXP_TYPE);
      break;

    case Token.GETPROP:
      visitGetProp(t, n, parent);
      typeable = !(parent.getType() == Token.ASSIGN &&
                   parent.getFirstChild() == n);
      break;

    case Token.GETELEM:
      visitGetElem(t, n);
      // The type of GETELEM is always unknown, so no point counting that.
      // If that unknown leaks elsewhere (say by an assignment to another
      // variable), then it will be counted.
      typeable = false;
      break;

    case Token.VAR:
      visitVar(t, n);
      typeable = false;
      break;

    case Token.NEW:
      visitNew(t, n);
      typeable = true;
      break;

    case Token.CALL:
      visitCall(t, n);
      typeable = !NodeUtil.isExpressionNode(parent);
      break;

    case Token.RETURN:
      visitReturn(t, n);
      typeable = false;
      break;

    case Token.DEC:
    case Token.INC:
      left = n.getFirstChild();
      validator.expectNumber(
          t, left, getJSType(left), "increment/decrement");
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.NOT:
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.VOID:
      ensureTyped(t, n, VOID_TYPE);
      break;

    case Token.TYPEOF:
      ensureTyped(t, n, STRING_TYPE);
      break;

    case Token.BITNOT:
      childType = getJSType(n.getFirstChild());
      if (!childType.matchesInt32Context()) {
        report(t, n, BIT_OPERATION, NodeUtil.opToStr(n.getType()),
            childType.toString());
      }
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.POS:
    case Token.NEG:
      left = n.getFirstChild();
      validator.expectNumber(t, left, getJSType(left), "sign operator");
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.EQ:
    case Token.NE: {
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());

      JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
      JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
      TernaryValue result =
          leftTypeRestricted.testForEquality(rightTypeRestricted);
      if (result != TernaryValue.UNKNOWN) {
        if (n.getType() == Token.NE) {
          result = result.not();
        }
        report(t, n, DETERMINISTIC_TEST, leftType.toString(),
            rightType.toString(), result.toString());
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;
    }

    case Token.SHEQ:
    case Token.SHNE: {
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());

      JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
      JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
      if (!leftTypeRestricted.canTestForShallowEqualityWith(
              rightTypeRestricted)) {
        report(t, n, DETERMINISTIC_TEST_NO_RESULT, leftType.toString(),
            rightType.toString());
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;
    }

    case Token.LT:
    case Token.LE:
    case Token.GT:
    case Token.GE:
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());
      if (rightType.isNumber()) {
        validator.expectNumber(
            t, n, leftType, "left side of numeric comparison");
      } else if (leftType.isNumber()) {
        validator.expectNumber(
            t, n, rightType, "right side of numeric comparison");
      } else if (leftType.matchesNumberContext() &&
                 rightType.matchesNumberContext()) {
        // OK.
      } else {
        // Whether the comparison is numeric will be determined at runtime
        // each time the expression is evaluated. Regardless, both operands
        // should match a string context.
        String message = "left side of comparison";
        validator.expectString(t, n, leftType, message);
        validator.expectNotNullOrUndefined(
            t, n, leftType, message, getNativeType(STRING_TYPE));
        message = "right side of comparison";
        validator.expectString(t, n, rightType, message);
        validator.expectNotNullOrUndefined(
            t, n, rightType, message, getNativeType(STRING_TYPE));
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.IN:
      left = n.getFirstChild();
      right = n.getLastChild();
      leftType = getJSType(left);
      rightType = getJSType(right);
      validator.expectObject(t, n, rightType, "'in' requires an object");
      validator.expectString(t, left, leftType, "left side of 'in'");
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.INSTANCEOF:
      left = n.getFirstChild();
      right = n.getLastChild();
      leftType = getJSType(left);
      rightType = getJSType(right).restrictByNotNullOrUndefined();

      validator.expectAnyObject(
          t, left, leftType, "deterministic instanceof yields false");
      validator.expectActualObject(
          t, right, rightType, "instanceof requires an object");
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.ASSIGN:
      visitAssign(t, n);
      typeable = false;
      break;

    case Token.ASSIGN_LSH:
    case Token.ASSIGN_RSH:
    case Token.ASSIGN_URSH:
    case Token.ASSIGN_DIV:
    case Token.ASSIGN_MOD:
    case Token.ASSIGN_BITOR:
    case Token.ASSIGN_BITXOR:
    case Token.ASSIGN_BITAND:
    case Token.ASSIGN_SUB:
    case Token.ASSIGN_ADD:
    case Token.ASSIGN_MUL:
    case Token.LSH:
    case Token.RSH:
    case Token.URSH:
    case Token.DIV:
    case Token.MOD:
    case Token.BITOR:
    case Token.BITXOR:
    case Token.BITAND:
    case Token.SUB:
    case Token.ADD:
    case Token.MUL:
      visitBinaryOperator(n.getType(), t, n);
      break;

    case Token.DELPROP:
      if (!isReference(n.getFirstChild())) {
        report(t, n, BAD_DELETE);
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.CASE:
      JSType switchType = getJSType(parent.getFirstChild());
      JSType caseType = getJSType(n.getFirstChild());
      validator.expectSwitchMatchesCase(t, n, switchType, caseType);
      typeable = false;
      break;

    case Token.WITH: {
      Node child = n.getFirstChild();
      childType = getJSType(child);
      validator.expectObject(
          t, child, childType, "with requires an object");
      typeable = false;
      break;
    }

    case Token.FUNCTION:
      visitFunction(t, n);
      break;

    // These nodes have no interesting type behavior.
    case Token.LABEL:
    case Token.LABEL_NAME:
    case Token.SWITCH:
    case Token.BREAK:
    case Token.CATCH:
    case Token.TRY:
    case Token.SCRIPT:
    case Token.EXPR_RESULT:
    case Token.BLOCK:
    case Token.EMPTY:
    case Token.DEFAULT:
    case Token.CONTINUE:
    case Token.DEBUGGER:
    case Token.THROW:
      typeable = false;
      break;

    // These nodes require data flow analysis.
    case Token.DO:
    case Token.FOR:
    case Token.IF:
    case Token.WHILE:
      typeable = false;
      break;

    // These nodes are typed during the type inference.
    case Token.AND:
    case Token.HOOK:
    case Token.OBJECTLIT:
    case Token.OR:
      if (n.getJSType() != null) { // If we didn't run type inference.
        ensureTyped(t, n);
      } else {
        // If this is an enum, then give that type to the objectlit as well.
        if ((n.getType() == Token.OBJECTLIT)
            && (parent.getJSType() instanceof EnumType)) {
          ensureTyped(t, n, parent.getJSType());
        } else {
          ensureTyped(t, n);
        }
      }
      if (n.getType() == Token.OBJECTLIT) {
        for (Node key : n.children()) {
          visitObjLitKey(t, key, n);
        }
      }
      break;

    default:
      report(t, n, UNEXPECTED_TOKEN, Token.name(n.getType()));
      ensureTyped(t, n);
      break;
  }

  // Don't count externs since the user's code may not even use that part.
  typeable = typeable && !inExterns;

  if (typeable) {
    doPercentTypedAccounting(t, n);
  }

  checkNoTypeCheckSection(n, false);
}

public void visit(NodeTraversal t, Node n, Node parent) {
  JSType childType;
  JSType leftType, rightType;
  Node left, right;
  // To be explicitly set to false if the node is not typeable.
  boolean typeable = true;

  switch (n.getType()) {
    case Token.NAME:
      typeable = visitName(t, n, parent);
      break;

    case Token.LP:
      // If this is under a FUNCTION node, it is a parameter list and can be
      // ignored here.
      if (parent.getType() != Token.FUNCTION) {
        ensureTyped(t, n, getJSType(n.getFirstChild()));
      } else {
        typeable = false;
      }
      break;

    case Token.COMMA:
      ensureTyped(t, n, getJSType(n.getLastChild()));
      break;

    case Token.TRUE:
    case Token.FALSE:
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.THIS:
      ensureTyped(t, n, t.getScope().getTypeOfThis());
      break;

    case Token.REF_SPECIAL:
      ensureTyped(t, n);
      break;

    case Token.GET_REF:
      ensureTyped(t, n, getJSType(n.getFirstChild()));
      break;

    case Token.NULL:
      ensureTyped(t, n, NULL_TYPE);
      break;

    case Token.NUMBER:
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.STRING:
      // Object literal keys are handled with OBJECTLIT
      if (!NodeUtil.isObjectLitKey(n, n.getParent())) {
        ensureTyped(t, n, STRING_TYPE);
        // Object literal keys are not typeable
      } else {
        typeable = false;
      }
      break;

    case Token.GET:
    case Token.SET:
      // Object literal keys are handled with OBJECTLIT
      typeable = false;
      break;

    case Token.ARRAYLIT:
      ensureTyped(t, n, ARRAY_TYPE);
      break;

    case Token.REGEXP:
      ensureTyped(t, n, REGEXP_TYPE);
      break;

    case Token.GETPROP:
      visitGetProp(t, n, parent);
      typeable = !(parent.getType() == Token.ASSIGN &&
                   parent.getFirstChild() == n);
      break;

    case Token.GETELEM:
      visitGetElem(t, n);
      // The type of GETELEM is always unknown, so no point counting that.
      // If that unknown leaks elsewhere (say by an assignment to another
      // variable), then it will be counted.
      typeable = false;
      break;

    case Token.VAR:
      visitVar(t, n);
      typeable = false;
      break;

    case Token.NEW:
      visitNew(t, n);
      typeable = true;
      break;

    case Token.CALL:
      visitCall(t, n);
      typeable = !NodeUtil.isExpressionNode(parent);
      break;

    case Token.RETURN:
      visitReturn(t, n);
      typeable = false;
      break;

    case Token.DEC:
    case Token.INC:
      left = n.getFirstChild();
      validator.expectNumber(
          t, left, getJSType(left), "increment/decrement");
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.NOT:
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.VOID:
      ensureTyped(t, n, VOID_TYPE);
      break;

    case Token.TYPEOF:
      ensureTyped(t, n, STRING_TYPE);
      break;

    case Token.BITNOT:
      childType = getJSType(n.getFirstChild());
      if (!childType.matchesInt32Context()) {
        report(t, n, BIT_OPERATION, NodeUtil.opToStr(n.getType()),
            childType.toString());
      }
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.POS:
    case Token.NEG:
      left = n.getFirstChild();
      validator.expectNumber(t, left, getJSType(left), "sign operator");
      ensureTyped(t, n, NUMBER_TYPE);
      break;

    case Token.EQ:
    case Token.NE: {
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());

      JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
      JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
      TernaryValue result =
          leftTypeRestricted.testForEquality(rightTypeRestricted);
      if (result != TernaryValue.UNKNOWN) {
        if (n.getType() == Token.NE) {
          result = result.not();
        }
        report(t, n, DETERMINISTIC_TEST, leftType.toString(),
            rightType.toString(), result.toString());
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;
    }

    case Token.SHEQ:
    case Token.SHNE: {
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());

      JSType leftTypeRestricted = leftType.restrictByNotNullOrUndefined();
      JSType rightTypeRestricted = rightType.restrictByNotNullOrUndefined();
      if (!leftTypeRestricted.canTestForShallowEqualityWith(
              rightTypeRestricted)) {
        report(t, n, DETERMINISTIC_TEST_NO_RESULT, leftType.toString(),
            rightType.toString());
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;
    }

    case Token.LT:
    case Token.LE:
    case Token.GT:
    case Token.GE:
      leftType = getJSType(n.getFirstChild());
      rightType = getJSType(n.getLastChild());
      if (rightType.isNumber()) {
        validator.expectNumber(
            t, n, leftType, "left side of numeric comparison");
      } else if (leftType.isNumber()) {
        validator.expectNumber(
            t, n, rightType, "right side of numeric comparison");
      } else if (leftType.matchesNumberContext() &&
                 rightType.matchesNumberContext()) {
        // OK.
      } else {
        // Whether the comparison is numeric will be determined at runtime
        // each time the expression is evaluated. Regardless, both operands
        // should match a string context.
        String message = "left side of comparison";
        validator.expectString(t, n, leftType, message);
        validator.expectNotNullOrUndefined(
            t, n, leftType, message, getNativeType(STRING_TYPE));
        message = "right side of comparison";
        validator.expectString(t, n, rightType, message);
        validator.expectNotNullOrUndefined(
            t, n, rightType, message, getNativeType(STRING_TYPE));
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.IN:
      left = n.getFirstChild();
      right = n.getLastChild();
      leftType = getJSType(left);
      rightType = getJSType(right);
      validator.expectObject(t, n, rightType, "'in' requires an object");
      validator.expectString(t, left, leftType, "left side of 'in'");
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.INSTANCEOF:
      left = n.getFirstChild();
      right = n.getLastChild();
      leftType = getJSType(left);
      rightType = getJSType(right).restrictByNotNullOrUndefined();

      validator.expectAnyObject(
          t, left, leftType, "deterministic instanceof yields false");
      validator.expectActualObject(
          t, right, rightType, "instanceof requires an object");
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.ASSIGN:
      visitAssign(t, n);
      typeable = false;
      break;

    case Token.ASSIGN_LSH:
    case Token.ASSIGN_RSH:
    case Token.ASSIGN_URSH:
    case Token.ASSIGN_DIV:
    case Token.ASSIGN_MOD:
    case Token.ASSIGN_BITOR:
    case Token.ASSIGN_BITXOR:
    case Token.ASSIGN_BITAND:
    case Token.ASSIGN_SUB:
    case Token.ASSIGN_ADD:
    case Token.ASSIGN_MUL:
    case Token.LSH:
    case Token.RSH:
    case Token.URSH:
    case Token.DIV:
    case Token.MOD:
    case Token.BITOR:
    case Token.BITXOR:
    case Token.BITAND:
    case Token.SUB:
    case Token.ADD:
    case Token.MUL:
      visitBinaryOperator(n.getType(), t, n);
      break;

    case Token.DELPROP:
      if (!isReference(n.getFirstChild())) {
        report(t, n, BAD_DELETE);
      }
      ensureTyped(t, n, BOOLEAN_TYPE);
      break;

    case Token.CASE:
      JSType switchType = getJSType(parent.getFirstChild());
      JSType caseType = getJSType(n.getFirstChild());
      validator.expectSwitchMatchesCase(t, n, switchType, caseType);
      typeable = false;
      break;

    case Token.WITH: {
      Node child = n.getFirstChild();
      childType = getJSType(child);
      validator.expectObject(
          t, child, childType, "with requires an object");
      typeable = false;
      break;
    }

    case Token.FUNCTION:
      visitFunction(t, n);
      break;

    // These nodes have no interesting type behavior.
    case Token.LABEL:
    case Token.LABEL_NAME:
    case Token.SWITCH:
    case Token.BREAK:
    case Token.CATCH:
    case Token.TRY:
    case Token.SCRIPT:
    case Token.EXPR_RESULT:
    case Token.BLOCK:
    case Token.EMPTY:
    case Token.DEFAULT:
    case Token.CONTINUE:
    case Token.DEBUGGER:
    case Token.THROW:
      typeable = false;
      break;

    // These nodes require data flow analysis.
    case Token.DO:
    case Token.FOR:
    case Token.IF:
    case Token.WHILE:
      typeable = false;
      break;

    // These nodes are typed during the type inference.
    case Token.AND:
    case Token.HOOK:
    case Token.OBJECTLIT:
    case Token.OR:
      if (n.getJSType() != null) { // If we didn't run type inference.
        ensureTyped(t, n);
      } else {
        // If this is an enum, then give that type to the objectlit as well.
        if ((n.getType() == Token.OBJECTLIT)
            && (parent.getJSType() instanceof EnumType)) {
          ensureTyped(t, n, parent.getJSType());
        } else {
          ensureTyped(t, n);
        }
      }
      if (n.getType() == Token.OBJECTLIT) {
        for (Node key : n.children()) {
          visitObjLitKey(t, key, n);
        }
      }
      break;

    default:
      report(t, n, UNEXPECTED_TOKEN, Token.name(n.getType()));
      ensureTyped(t, n);
      break;
  }

  // Don't count externs since the user's code may not even use that part.
  typeable = typeable && !inExterns;

  if (typeable) {
    doPercentTypedAccounting(t, n);
  }

  checkNoTypeCheckSection(n, false);
}

static String strEscape(String s, char quote,
                        String doublequoteEscape,
                        String singlequoteEscape,
                        String backslashEscape,
                        CharsetEncoder outputCharsetEncoder) {
  StringBuilder sb = new StringBuilder(s.length() + 2);
  sb.append(quote);
  for (int i = 0; i < s.length(); i++) {
    char c = s.charAt(i);
    switch (c) {
      case '\0': sb.append("\\0"); break;
      case '\n': sb.append("\\n"); break;
      case '\r': sb.append("\\r"); break;
      case '\t': sb.append("\\t"); break;
      case '\\': sb.append(backslashEscape); break;
      case '\"': sb.append(doublequoteEscape); break;
      case '\'': sb.append(singlequoteEscape); break;
      case '>': 
        // Break --> into --\> or ]]> into ]]\>
        if (i >= 2 &&
            ((s.charAt(i - 1) == '-' && s.charAt(i - 2) == '-') ||
             (s.charAt(i - 1) == ']' && s.charAt(i - 2) == ']'))) {
          sb.append("\\>");
        } else {
          sb.append(c);
        }
        break;
      case '<':
        // Break </script into <\/script
        final String END_SCRIPT = "/script";

        // Break <!-- into <\!--
        final String START_COMMENT = "!--";

        if (s.regionMatches(true, i + 1, END_SCRIPT, 0,
                            END_SCRIPT.length())) {
          sb.append("<\\");
        } else if (s.regionMatches(false, i + 1, START_COMMENT, 0,
                                   START_COMMENT.length())) {
          sb.append("<\\");
        } else {
          sb.append(c);
        }
        break;
      default:
        // If we're given an outputCharsetEncoder, then check if the
        //  character can be represented in this character set.
        if (outputCharsetEncoder != null) {
          if (outputCharsetEncoder.canEncode(c)) {
            sb.append(c);
          } else {
            // Unicode-escape the character.
            appendHexJavaScriptRepresentation(sb, c);
          }
        } else {
          // No charsetEncoder provided - pass straight latin characters
          // through, and escape the rest.  Doing the explicit character
          // check is measurably faster than using the CharsetEncoder.
          if (c >= 0x20 && c <= 0x7e) { // Adjusted to include space and exclude DEL
            sb.append(c);
          } else {
            // Other characters can be misinterpreted by some js parsers,
            // or perhaps mangled by proxies along the way,
            // so we play it safe and unicode escape them.
            appendHexJavaScriptRepresentation(sb, c);
          }
        }
    }
  }
  sb.append(quote);
  return sb.toString();
}

private Node tryFoldShift(Node n, Node left, Node right) {
  if (left.getType() == Token.NUMBER &&
      right.getType() == Token.NUMBER) {

    double result;
    double lval = left.getDouble();
    double rval = right.getDouble();

    // check ranges.  We do not do anything that would clip the double to
    // a 32-bit range, since the user likely does not intend that.
    if (!(lval >= Integer.MIN_VALUE && lval <= Integer.MAX_VALUE)) {
      error(BITWISE_OPERAND_OUT_OF_RANGE, left);
      return n;
    }

    // only the lower 5 bits are used when shifting, so don't do anything
    // if the shift amount is outside [0,32)
    if (!(rval >= 0 && rval < 32)) {
      error(SHIFT_AMOUNT_OUT_OF_BOUNDS, right);
      return n;
    }

    // Convert the numbers to ints
    int lvalInt = (int) lval;
    if (lvalInt != lval) {
      error(FRACTIONAL_BITWISE_OPERAND, left);
      return n;
    }

    int rvalInt = (int) rval;
    if (rvalInt != rval) {
      error(FRACTIONAL_BITWISE_OPERAND, right);
      return n;
    }

    switch (n.getType()) {
      case Token.LSH:
        result = lvalInt << rvalInt;
        break;
      case Token.RSH:
        result = lvalInt >> rvalInt;
        break;
      case Token.URSH:
        // JavaScript handles zero shifts on signed numbers differently than
        // Java as an Java int can not represent the unsigned 32-bit number
        // where JavaScript can so use a long here.
        result = ((long) lvalInt & 0xFFFFFFFFL) >>> rvalInt;
        break;
      default:
        throw new AssertionError("Unknown shift operator: " +
            Node.tokenToName(n.getType()));
    }

    Node newNumber = Node.newNumber(result);
    n.getParent().replaceChild(n, newNumber);
    reportCodeChange();

    return newNumber;
  }

  return n;
}

public int read(byte b[], int offset, int len) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    } else if (offset < 0 || len < 0) {
        throw new IndexOutOfBoundsException();
    } else if (offset > b.length || offset + len > b.length) {
        throw new IndexOutOfBoundsException();
    } else if (len == 0) {
        return 0;
    } else {
        /*
         Rationale for while-loop on (readLen == 0):
         -----
         Base64.readResults() usually returns > 0 or EOF (-1).  In the
         rare case where it returns 0, we just keep trying.

         This is essentially an undocumented contract for InputStream
         implementors that want their code to work properly with
         java.io.InputStreamReader, since the latter hates it when
         InputStream.read(byte[]) returns a zero.  Unfortunately our
         readResults() call must return 0 if a large amount of the data
         being decoded was non-base64, so this while-loop enables proper
         interop with InputStreamReader for that scenario.
         -----
         This is a fix for CODEC-101
        */
        int readLen;
        do {
            if (!base64.hasData()) {
                byte[] buf = new byte[doEncode ? 4096 : 8192];
                int c = in.read(buf);
                // A little optimization to avoid System.arraycopy()
                // when possible.
                if (c > 0 && b.length == len) {
                    base64.setInitialBuffer(b, offset, len);
                }
                if (doEncode) {
                    base64.encode(buf, 0, c);
                } else {
                    base64.decode(buf, 0, c);
                }
            }
            readLen = base64.readResults(b, offset, len);
        } while (readLen == 0);
        return readLen;
    }
}

