InputStream decode(final InputStream in, final Coder coder,
        byte[] password) throws IOException {
    byte propsByte = coder.properties[0];
    long dictSize = coder.properties[1] & 0xFF;
    for (int i = 1; i < 4; i++) {
        dictSize |= ((coder.properties[i + 1] & 0xFF) << (8 * i));
    }
    if (dictSize > LZMAInputStream.DICT_SIZE_MAX) {
        throw new IOException("Dictionary larger than 4GiB maximum size");
    }
    return new LZMAInputStream(in, -1, propsByte, (int) dictSize);
}

InputStream decode(final InputStream in, final Coder coder,
        byte[] password) throws IOException {
    if (coder.properties.length < 5) {
        throw new IOException("Invalid properties length");
    }
    byte propsByte = coder.properties[0];
    long dictSize = 0;
    for (int i = 0; i < 4; i++) {
        dictSize |= ((long) coder.properties[i + 1] & 0xFF) << (8 * i);
    }
    if (dictSize > LZMAInputStream.DICT_SIZE_MAX) {
        throw new IOException("Dictionary larger than 4GiB maximum size");
    }
    return new LZMAInputStream(in, -1, propsByte, (int) dictSize);
}

public static long skip(InputStream input, long numToSkip) throws IOException {
    long available = numToSkip;
    while (numToSkip > 0) {
        long skipped = input.skip(numToSkip);
        if (skipped == 0) {
            // If no bytes were skipped, we should try to read one byte to see if we've reached the end of the stream
            int read = input.read();
            if (read == -1) {
                break; // End of stream reached
            } else {
                numToSkip--; // One byte was read, so decrement numToSkip
            }
        } else {
            numToSkip -= skipped;
        }
    }

    return available - numToSkip;
}

public static long skip(InputStream input, long numToSkip) throws IOException {
    long totalSkipped = 0;
    while (numToSkip > 0) {
        long skipped = input.skip(numToSkip);
        if (skipped == 0) {
            // If no bytes are skipped, try to read one byte to see if we've reached the end of the stream
            int read = input.read();
            if (read == -1) {
                break; // End of stream reached
            } else {
                totalSkipped++;
                numToSkip--;
            }
        } else {
            totalSkipped += skipped;
            numToSkip -= skipped;
        }
    }
    return totalSkipped;
}

