public void serializeAsColumn(Object bean, JsonGenerator jgen, SerializerProvider prov)
    throws Exception
{
    Object value = get(bean);
    if (value == null) { // Handle null values
        if (_nullSerializer != null) {
            _nullSerializer.serialize(null, jgen, prov);
        } else {
            jgen.writeNull(); // Write null if no custom null serializer is provided
        }
    } else {
        // Find the appropriate serializer for the value
        JsonSerializer<Object> ser = _serializer;
        if (ser == null) {
            Class<?> cls = value.getClass();
            PropertySerializerMap map = _dynamicSerializers;
            ser = map.serializerFor(cls);
            if (ser == null) {
                ser = _findAndAddDynamic(map, cls, prov);
            }
        }
        // Check if the value should be suppressed based on the suppressable value
        if (_suppressableValue != null) {
            if (MARKER_FOR_EMPTY == _suppressableValue) {
                if (ser.isEmpty(value)) {
                    serializeAsPlaceholder(bean, jgen, prov); // Serialize a placeholder if the value is empty
                    return;
                }
            } else if (_suppressableValue.equals(value)) {
                serializeAsPlaceholder(bean, jgen, prov); // Serialize a placeholder if the value matches the suppressable value
                return;
            }
        }
        // Handle self-references to avoid infinite recursion
        if (value == bean) {
            _handleSelfReference(bean, ser);
        }
        // Serialize the value using the appropriate serializer
        if (_typeSerializer == null) {
            ser.serialize(value, jgen, prov);
        } else {
            ser.serializeWithType(value, jgen, prov, _typeSerializer);
        }
    }
}

public void serializeAsColumn(Object bean, JsonGenerator jgen, SerializerProvider prov)
    throws Exception
{
    Object value = get(bean);
    if (value == null) { // nulls need specialized handling
        if (_nullSerializer != null) {
            _nullSerializer.serialize(null, jgen, prov);
        } else { // can NOT suppress entries in tabular output
            jgen.writeNull();
        }
        return; // Exit early after handling null
    }

    // Find or create a serializer for the value
    JsonSerializer<Object> ser = _serializer;
    if (ser == null) {
        Class<?> cls = value.getClass();
        PropertySerializerMap map = _dynamicSerializers;
        ser = map.serializerFor(cls);
        if (ser == null) {
            ser = _findAndAddDynamic(map, cls, prov);
        }
    }

    // Check if the value should be suppressed based on _suppressableValue
    if (_suppressableValue != null) {
        if (MARKER_FOR_EMPTY == _suppressableValue) {
            if (ser.isEmpty(value)) { // can NOT suppress entries in tabular output
                serializeAsPlaceholder(bean, jgen, prov);
                return;
            }
        } else if (_suppressableValue.equals(value)) { // can NOT suppress entries in tabular output
            serializeAsPlaceholder(bean, jgen, prov);
            return;
        }
    }

    // For non-nulls: simple check for direct cycles
    if (value == bean) {
        _handleSelfReference(bean, ser);
    }

    // Serialize the value using the appropriate serializer
    if (_typeSerializer == null) {
        ser.serialize(value, jgen, prov);
    } else {
        ser.serializeWithType(value, jgen, prov, _typeSerializer);
    }
}

