    int maxLevels = 5;
    for (int i = 0; i < maxLevels && node != null; i++) {
        if (node instanceof Element) {
            Element el = (Element) node;
            if (el.tag().preserveWhitespace()) {
                return true;
            }
            node = el.parent();
        } else {
            break;
        }
    }
    return false;
}

static boolean preserveWhitespace(Node node) {
    // looks only at this element and five levels up, to prevent recursion & needless stack searches
    int maxLevels = 5;
    while (node != null && node instanceof Element && maxLevels > 0) {
        Element el = (Element) node;
        if (el.tag().preserveWhitespace()) {
            return true;
        }
        node = el.parent();
        maxLevels--;
    }
    return false;
}

void insert(Token.Comment commentToken) {
    Comment comment = new Comment(commentToken.getData());
    Node insert = comment;
    if (commentToken.bogus) { // xml declarations are emitted as bogus comments (which is right for html, but not xml)
        // so we do a bit of a hack and parse the data as an element to pull the attributes out
        String data = comment.getData();
        if (data.length() > 1 && (data.startsWith("!") || data.startsWith("?"))) {
            // Ensure the data is properly enclosed for parsing
            String enclosedData = "<" + data.substring(1, data.length() - 1) + ">";
            Document doc = Jsoup.parse(enclosedData, baseUri, Parser.xmlParser());
            if (!doc.children().isEmpty()) { // Check if there are any children to avoid IndexOutOfBoundsException
                Element el = doc.child(0);
                insert = new XmlDeclaration(settings.normalizeTag(el.tagName()), data.startsWith("!"));
                insert.attributes().addAll(el.attributes());
            }
        }
    }
    insertNode(insert);
}

